const express = require('express');
const router = express.Router();
const { verifyRegistrationResponse } = require('@simplewebauthn/server');

router.post('/api/webauthn/register/verify', authenticateSession, async (req, res) => {
  const targetUserId = req.session.userId;
  const { registrationResponse } = req.body;

  const expectedChallenge = await redis.get(`reg_chal:${targetUserId}`);
  const verification = await verifyRegistrationResponse({
    response: registrationResponse,
    expectedChallenge,
    expectedOrigin: process.env.WEBAUTHN_ORIGIN,
    expectedRPID: process.env.WEBAUTHN_RPID
  });

  if (!verification.verified || !verification.registrationInfo) {
    return res.status(400).json({ error: 'Verification failed' });
  }

  const { credentialID, credentialPublicKey, counter } = verification.registrationInfo;
  await db.query(
    'INSERT INTO user_passkeys (user_id, credential_id, public_key, counter) VALUES ($1, $2, $3, $4)',
    [targetUserId, Buffer.from(credentialID).toString('base64url'), Buffer.from(credentialPublicKey).toString('base64'), counter]
  );

  res.json({ success: true, verified: true });
});
